def comps(grid):
    H,W=len(grid),len(grid[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]:
                c=[(i,j)]; q=deque([(i,j)]); cells=[]
                while q:
                    x,y=q.popleft()
                    if (x,y) in seen: continue
                    seen.add((x,y)); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and grid[nx][ny] and (nx,ny) not in seen:
                            q.append((nx,ny))
                out.append(cells)
