def f(grid):
    H,W=len(grid),len(grid[0])
    shapes=[]
    for comp in comps(grid):
        xs=[c[0] for c in comp]; ys=[c[1] for c in comp]
        h=max(xs)-min(xs)+1; w=max(ys)-min(ys)+1
        b=[[0]*w for _ in range(h)]
        for x,y in comp: b[x-min(xs)][y-min(ys)]=grid[x][y]
        shapes.append((b,(min(xs),min(ys))))
    # order by column position of shape (leftmost first)
    shapes.sort(key=lambda s:s[1][1])
    Ht=max(s[0][0] for s in shapes)
    Wt=sum(len(s[0]) for s in shapes)
    out=[[0]*Wt for _ in range(Ht)]
    for idx,(b,_) in enumerate(shapes):
        for i in range(len(b)):
            for j in range(len(b[0])):
                out[i][idx*len(b[0])+j]=b[i][j]
    return out
